def collect_unique_ids(rows, seen=set()):
    result = []
    for row in rows:
        id_ = row.split(",")[0]
        if id_ not in seen:
            seen.add(id_)
            result.append(id_)
    return result

print(collect_unique_ids(["1,a", "2,b"]))
print(collect_unique_ids(["1,c", "3,d"]))

